type PdSchema = Record<string, any>;
const pdObject = (properties: Record<string, PdSchema>, required = Object.keys(properties), description?: string): PdSchema => ({
  type: "object", additionalProperties: false, properties, required, ...(description ? { description } : {}),
});
const pdString: PdSchema = { type: "string" };
const pdBoolean: PdSchema = { type: "boolean" };
const pdInteger: PdSchema = { type: "integer" };
