const pdUserId: PdSchema = { type: "string", minLength: 1, description: "Opaque exact account identifier, at most 4096 UTF-8 bytes and no NUL. Preserve issuer/subject punctuation and Unicode; it is not a UUID." };
const pdDate: PdSchema = { type: "string", format: "date", description: "Exact YYYY-MM-DD calendar date; database date rules reject impossible dates." };
const pdTime: PdSchema = { type: "string", format: "date-time" };
const pdNullable = (schema: PdSchema): PdSchema => ({ ...schema, nullable: true, ...(schema.enum ? { enum: [...schema.enum, null] } : {}) });
const pdArray = (items: PdSchema, maxItems?: number): PdSchema => ({ type: "array", items, ...(maxItems === undefined ? {} : { maxItems }) });
const pdEnum = (...values: string[]): PdSchema => ({ type: "string", enum: values });
const pdText = (maxLength: number, minLength = 1): PdSchema => ({ type: "string", minLength, maxLength, description: "Trimmed text; NUL is rejected." });
const pdKey: PdSchema = { type: "string", format: "uuid", pattern: "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$", description: "One UUIDv4 per intended operation. Retain the exact original key and payload after an uncertain result; reuse with different details conflicts." };
const pdSuccess = pdObject({ success: { type: "boolean", enum: [true] } });
const pdEmptyQuery = pdObject({}, [], "This endpoint rejects all query parameters.");
const pdIgnoredQuery: PdSchema = { type: "object", additionalProperties: true, description: "The handler does not inspect query parameters; they do not change scope or filter records." };
const pdError = (description: string): PdSchema => ({ ...pdObject({ error: pdString, code: pdString, requestId: pdString }), description });
const pdRetryWrite = "Preserve the original UUIDv4 submission key and full request after response loss. A replay rechecks current authorization and compares the original payload; do not create a new logical write until its outcome is known.";
